import type { FC } from "react";
import React, { useEffect, useRef, useImperativeHandle, forwardRef } from "react";
import { Crepe, CrepeInstance } from "@milkdown/crepe";
import { listener, listenerCtx } from "@milkdown/kit/plugin/listener";

import "@milkdown/crepe/theme/common/style.css";
import "@milkdown/crepe/theme/frame.css";

export interface MilkdownEditorRef {
    getValue: () => string;
    insertValue: (value: string) => void;
    setValue: (value: string) => void;
    focus: () => void;
    destroy: () => void;
}

interface MilkdownEditorProps {
    defaultValue?: string;
    onChange?: (markdown: string) => void;
    onFocus?: () => void;
    onBlur?: () => void;
    onReady?: (editor: CrepeInstance) => void;
    readonly?: boolean;
}

export const MilkdownEditor = forwardRef<MilkdownEditorRef, MilkdownEditorProps>(({
    defaultValue = "",
    onChange,
    onFocus,
    onBlur,
    onReady,
    readonly = false
}, ref) => {
    const editorRef = useRef<HTMLDivElement>(null);
    const crepeRef = useRef<CrepeInstance | null>(null);
    const isMountedRef = useRef(false);
    const defaultValueRef = useRef(defaultValue);
    const onChangeRef = useRef(onChange);
    const onFocusRef = useRef(onFocus);
    const onBlurRef = useRef(onBlur);

    // 更新 ref 以在回调中使用最新值
    onChangeRef.current = onChange;
    onFocusRef.current = onFocus;
    onBlurRef.current = onBlur;

    useImperativeHandle(ref, () => ({
        getValue: () => {
            return crepeRef.current?.getMarkdown() ?? "";
        },
        insertValue: (value: string) => {
            if (crepeRef.current) {
                // 获取当前内容并追加
                const currentValue = crepeRef.current.getMarkdown();
                const newValue = currentValue + value;
                setEditorValue(newValue);
            }
        },
        setValue: (value: string) => {
            setEditorValue(value);
        },
        focus: () => {
            if (crepeRef.current) {
                const editor = editorRef.current?.querySelector('.milkdown');
                if (editor) {
                    (editor as HTMLElement).focus();
                }
            }
        },
        destroy: () => {
            if (crepeRef.current) {
                crepeRef.current.destroy();
                crepeRef.current = null;
            }
        }
    }));

    // 设置编辑器值的方法
    const setEditorValue = (value: string) => {
        if (crepeRef.current) {
            // 销毁当前编辑器并重新创建
            const currentRoot = editorRef.current;
            if (currentRoot) {
                crepeRef.current.destroy();
                crepeRef.current = null;
                
                // 延迟重新创建编辑器
                setTimeout(() => {
                    if (isMountedRef.current && currentRoot) {
                        const crepe = new Crepe({
                            root: currentRoot,
                            defaultValue: value,
                        });
                        
                        crepe.create().then(() => {
                            crepeRef.current = crepe;
                            setupEditor(crepe);
                        });
                    }
                }, 100);
            }
        }
    };

    // 设置编辑器的监听器
    const setupEditor = (crepe: CrepeInstance) => {
        // 设置只读模式
        if (readonly) {
            crepe.setReadonly(true);
        }

        // 监听内容变化
        crepe.on((ctx) => {
            const listenerPlugin = ctx.get(listenerCtx);
            listenerPlugin.markdownUpdated((ctx, markdown, prevMarkdown) => {
                if (markdown !== prevMarkdown && onChangeRef.current) {
                    onChangeRef.current(markdown);
                }
            });
            listenerPlugin.focus(() => {
                if (onFocusRef.current) onFocusRef.current();
            });
            listenerPlugin.blur(() => {
                if (onBlurRef.current) onBlurRef.current();
            });
        });

        // 通知编辑器已就绪
        if (onReady) {
            onReady(crepe);
        }
    };

    useEffect(() => {
        isMountedRef.current = true;
        defaultValueRef.current = defaultValue;

        if (!editorRef.current || crepeRef.current) return;

        const crepe = new Crepe({
            root: editorRef.current,
            defaultValue: defaultValue,
        });

        crepe.create().then(() => {
            crepeRef.current = crepe;
            setupEditor(crepe);
        }).catch((err) => {
            console.error("Failed to create Milkdown editor:", err);
        });

        return () => {
            isMountedRef.current = false;
            if (crepeRef.current) {
                crepeRef.current.destroy();
                crepeRef.current = null;
            }
        };
    }, []);

    // 监听只读状态变化
    useEffect(() => {
        if (crepeRef.current) {
            crepeRef.current.setReadonly(readonly);
        }
    }, [readonly]);

    return (
        <div
            ref={editorRef}
            className="milkdown-editor-container"
            style={{
                width: '100%',
                height: '100%',
                minHeight: '400px'
            }}
        />
    );
});

MilkdownEditor.displayName = 'MilkdownEditor';
